  1	import java.io.PrintStream;
  2	import java.util.ArrayList;
  3	import java.util.Arrays;
  4	import java.util.List;
  5	
  6	final class MST {
  7	    private static final int NO_EDGE = 0;
  8	    private static final int ROOT_PARENT = -1;
  9	    private static final int START_VERTEX = 0;
 10	
 11	    private MST() {}
 12	
 13	    record Edge(int from, int to, int weight) {}
 14	
 15	    record Result(List<Edge> edges, int totalWeight) {
 16	        Result {
 17	            edges = List.copyOf(edges);
 18	        }
 19	
 20	        String render() {
 21	            StringBuilder output = new StringBuilder("Edge \tWeight\n");
 22	            for (Edge edge : edges) {
 23	                output.append(edge.from())
 24	                    .append(" - ")
 25	                    .append(edge.to())
 26	                    .append('\t')
 27	                    .append(edge.weight())
 28	                    .append('\n');
 29	            }
 30	            return output.toString();
 31	        }
 32	
 33	        void printTo(PrintStream out) {
 34	            out.print(render());
 35	        }
 36	    }
 37	
 38	    @FunctionalInterface
 39	    private interface NeighborVisitor {
 40	        void visit(int vertex, int weight);
 41	    }
 42	
 43	    private static final class Graph {
 44	        private final int[][] adjacencyMatrix;
 45	
 46	        private Graph(int[][] adjacencyMatrix) {
 47	            this.adjacencyMatrix = adjacencyMatrix;
 48	        }
 49	
 50	        static Graph fromAdjacencyMatrix(int[][] adjacencyMatrix) {
 51	            validateAdjacencyMatrix(adjacencyMatrix);
 52	            return new Graph(copyAdjacencyMatrix(adjacencyMatrix));
 53	        }
 54	
 55	        static Graph sampleGraph() {
 56	            return fromAdjacencyMatrix(new int[][] {
 57	                { 0, 2, 0, 6, 0 },
 58	                { 2, 0, 3, 8, 5 },
 59	                { 0, 3, 0, 0, 7 },
 60	                { 6, 8, 0, 0, 9 },
 61	                { 0, 5, 7, 9, 0 }
 62	            });
 63	        }
 64	
 65	        int vertexCount() {
 66	            return adjacencyMatrix.length;
 67	        }
 68	
 69	        int edgeWeight(int from, int to) {
 70	            return adjacencyMatrix[from][to];
 71	        }
 72	
 73	        boolean hasEdge(int from, int to) {
 74	            return edgeWeight(from, to) != NO_EDGE;
 75	        }
 76	
 77	        void forEachNeighbor(int from, NeighborVisitor visitor) {
 78	            for (int to = 0; to < vertexCount(); to++) {
 79	                if (hasEdge(from, to)) {
 80	                    visitor.visit(to, edgeWeight(from, to));
 81	                }
 82	            }
 83	        }
 84	
 85	        private static int[][] copyAdjacencyMatrix(int[][] adjacencyMatrix) {
 86	            int[][] copy = new int[adjacencyMatrix.length][];
 87	            for (int rowIndex = 0; rowIndex < adjacencyMatrix.length; rowIndex++) {
 88	                copy[rowIndex] = Arrays.copyOf(adjacencyMatrix[rowIndex], adjacencyMatrix[rowIndex].length);
 89	            }
 90	            return copy;
 91	        }
 92	
 93	        private static void validateAdjacencyMatrix(int[][] graph) {
 94	            if (graph == null) {
 95	                throw new IllegalArgumentException("Graph must not be null.");
 96	            }
 97	
 98	            if (graph.length == 0) {
 99	                throw new IllegalArgumentException("Graph must contain at least one vertex.");
100	            }
101	
102	            for (int rowIndex = 0; rowIndex < graph.length; rowIndex++) {
103	                int[] row = graph[rowIndex];
104	                if (row == null) {
105	                    throw new IllegalArgumentException("Graph rows must not be null.");
106	                }
107	
108	                if (row.length != graph.length) {
109	                    throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
110	                }
111	
112	                for (int columnIndex = rowIndex + 1; columnIndex < graph.length; columnIndex++) {
113	                    if (row[columnIndex] != graph[columnIndex][rowIndex]) {
114	                        throw new IllegalArgumentException(
115	                            "Graph must represent an undirected adjacency matrix."
116	                        );
117	                    }
118	                }
119	            }
120	        }
121	    }
122	
123	    private static final class PrimAlgorithm {
124	        private final Graph graph;
125	        private final PrimState state;
126	
127	        PrimAlgorithm(Graph graph) {
128	            this.graph = graph;
129	            this.state = new PrimState(graph.vertexCount());
130	        }
131	
132	        Result compute() {
133	            for (int count = 0; count < graph.vertexCount() - 1; count++) {
134	                int currentVertex = state.selectNextVertex();
135	
136	                if (currentVertex == -1) {
137	                    throw new IllegalStateException("Graph must be connected.");
138	                }
139	
140	                includeAndRelax(currentVertex);
141	            }
142	
143	            return state.toResult(graph);
144	        }
145	
146	        private void includeAndRelax(int currentVertex) {
147	            state.include(currentVertex);
148	            graph.forEachNeighbor(currentVertex,
149	                (neighbor, edgeWeight) -> state.updateConnection(neighbor, currentVertex, edgeWeight));
150	        }
151	    }
152	
153	    private static final class PrimState {
154	        private final VertexState[] vertices;
155	
156	        PrimState(int vertexCount) {
157	            this.vertices = new VertexState[vertexCount];
158	            for (int vertex = 0; vertex < vertexCount; vertex++) {
159	                vertices[vertex] = new VertexState();
160	            }
161	
162	            vertices[START_VERTEX].bestEdgeWeight = 0;
163	            vertices[START_VERTEX].parent = ROOT_PARENT;
164	        }
165	
166	        int selectNextVertex() {
167	            int minValue = Integer.MAX_VALUE;
168	            int minIndex = -1;
169	
170	            for (int vertex = 0; vertex < vertices.length; vertex++) {
171	                VertexState vertexState = vertices[vertex];
172	                if (!vertexState.includedInMst && vertexState.bestEdgeWeight < minValue) {
173	                    minValue = vertexState.bestEdgeWeight;
174	                    minIndex = vertex;
175	                }
176	            }
177	
178	            return minIndex;
179	        }
180	
181	        void include(int vertex) {
182	            vertices[vertex].includedInMst = true;
183	        }
184	
185	        boolean isIncluded(int vertex) {
186	            return vertices[vertex].includedInMst;
187	        }
188	
189	        void updateConnection(int vertex, int newParent, int edgeWeight) {
190	            VertexState vertexState = vertices[vertex];
191	            if (!vertexState.includedInMst && edgeWeight < vertexState.bestEdgeWeight) {
192	                vertexState.parent = newParent;
193	                vertexState.bestEdgeWeight = edgeWeight;
194	            }
195	        }
196	
197	        Result toResult(Graph graph) {
198	            List<Edge> edges = new ArrayList<>();
199	            int totalWeight = 0;
200	
201	            for (int vertex = 1; vertex < graph.vertexCount(); vertex++) {
202	                int from = vertices[vertex].parent;
203	                int weight = graph.edgeWeight(from, vertex);
204	
205	                edges.add(new Edge(from, vertex, weight));
206	                totalWeight += weight;
207	            }
208	
209	            return new Result(edges, totalWeight);
210	        }
211	    }
212	
213	    private static final class VertexState {
214	        private int parent;
215	        private int bestEdgeWeight = Integer.MAX_VALUE;
216	        private boolean includedInMst;
217	    }
218	
219	    static Result computeMinimumSpanningTree(int[][] graph) {
220	        return computeMinimumSpanningTree(Graph.fromAdjacencyMatrix(graph));
221	    }
222	
223	    private static Result computeMinimumSpanningTree(Graph graph) {
224	        return new PrimAlgorithm(graph).compute();
225	    }
226	
227	    public static void main(String[] args)
228	    {
229	        Result result = computeMinimumSpanningTree(Graph.sampleGraph());
230	        result.printTo(System.out);
231	    }
232	}
